def first_max(values):
    return values.index(max(values))


def bellman(environment, values, gamma, state, action):
    world = environment.world
    total = 0
    for cell, numerator in environment.transitions[state][action]:
        target = world.state_index[cell]
        future = 0 if target is None else gamma * values[target] // 100
        total += numerator * (10000 * environment.reward(cell) + future)
    return total // environment.slip_total


def action_values(environment, values, gamma, state):
    return [bellman(environment, values, gamma, state, action) for action in range(4)]


def greedy_policy(environment, values, gamma):
    return [
        first_max(action_values(environment, values, gamma, state))
        for state in range(len(values))
    ]


def value_iteration(environment, gamma, theta):
    values = [0] * len(environment.world.states)
    changes = []
    while True:
        updated = [
            max(action_values(environment, values, gamma, state))
            for state in range(len(values))
        ]
        change = max(abs(new - old) for new, old in zip(updated, values))
        changes.append(change)
        values = updated
        if change <= theta:
            return values, changes


def in_place_value_iteration(environment, gamma, theta):
    values = [0] * len(environment.world.states)
    sweeps = 0
    while True:
        sweeps += 1
        delta = 0
        for state in range(len(values)):
            value = max(action_values(environment, values, gamma, state))
            delta = max(delta, abs(value - values[state]))
            values[state] = value
        if delta <= theta:
            return values, sweeps


def evaluate_policy(environment, policy, initial, gamma, theta):
    values = list(initial)
    sweeps = 0
    while True:
        sweeps += 1
        delta = 0
        for state, action in enumerate(policy):
            value = bellman(environment, values, gamma, state, action)
            delta = max(delta, abs(value - values[state]))
            values[state] = value
        if delta <= theta:
            return values, sweeps


def policy_iteration(environment, gamma, theta):
    start = environment.world.start_state
    policy = [0] * len(environment.world.states)
    values = [0] * len(policy)
    rounds = []
    while True:
        values, sweeps = evaluate_policy(environment, policy, values, gamma, theta)
        improved = greedy_policy(environment, values, gamma)
        changes = sum(new != old for new, old in zip(improved, policy))
        rounds.append((sweeps, changes, values[start]))
        policy = improved
        if changes == 0:
            return policy, values, rounds

WALL = "#"
FLOOR = "."
ICE = "~"
GOAL = "G"
PIT = "P"
START = "S"
ACTION_LETTERS = "NESW"
ROW_STEPS = (-1, 0, 1, 0)
COLUMN_STEPS = (0, 1, 0, -1)
MULTIPLIER = 48271
MODULUS = 2147483647


class World:
    def __init__(self, rows, cols, kinds, wind, rewards):
        self.rows = rows
        self.cols = cols
        self.kinds = kinds
        self.wind = wind
        self.terminal_rewards = rewards
        self.states = []
        self.terminals = []
        self.state_index = [None] * len(kinds)
        self.terminal_index = [None] * len(kinds)
        for cell, kind in enumerate(kinds):
            if kind in (GOAL, PIT):
                self.terminal_index[cell] = len(self.terminals)
                self.terminals.append(cell)
            elif kind != WALL:
                self.state_index[cell] = len(self.states)
                self.states.append(cell)
        self.start = kinds.index(START)
        self.start_state = self.state_index[self.start]

    def is_terminal(self, cell):
        return self.terminal_index[cell] is not None

    def terminal_name(self, cell):
        return "goal" if self.kinds[cell] == GOAL else "pit"

    def move(self, cell, direction):
        target = cell + ROW_STEPS[direction] * self.cols + COLUMN_STEPS[direction]
        if self.kinds[target] == WALL:
            target = cell
        if self.is_terminal(target):
            return target
        for _ in range(self.wind[cell % self.cols]):
            above = target - self.cols
            if self.kinds[above] == WALL:
                break
            target = above
            if self.is_terminal(target):
                break
        return target


def read_world(path):
    with open(path) as file:
        lines = file.read().splitlines()
    rows = int(lines[0].split()[1])
    cols = int(lines[1].split()[1])
    kinds = "".join(lines[2:2 + rows])
    wind = [int(digit) for digit in lines[2 + rows].split()[1]]
    rewards = [int(value) for value in lines[3 + rows].split()[1:]]
    return World(rows, cols, kinds, wind, rewards)


class RandomGenerator:
    def __init__(self, seed):
        self.value = seed

    def draw(self):
        self.value = MULTIPLIER * self.value % MODULUS
        return self.value


class Environment:
    def __init__(self, world, step_reward, slip_total, floor_slip, ice_slip):
        self.world = world
        self.step_reward = step_reward
        self.slip_total = slip_total
        self.floor_slip = floor_slip
        self.ice_slip = ice_slip
        self.moves = [
            [world.move(cell, direction) for direction in range(4)] for cell in world.states
        ]
        self.transitions = [
            [self.build_transitions(state, action) for action in range(4)]
            for state in range(len(world.states))
        ]

    def slip(self, state):
        if self.world.kinds[self.world.states[state]] == ICE:
            return self.ice_slip
        return self.floor_slip

    def slip_outcomes(self, state, action):
        slip = self.slip(state)
        return (
            (action, self.slip_total - 2 * slip),
            ((action + 1) % 4, slip),
            ((action + 3) % 4, slip),
        )

    def build_transitions(self, state, action):
        return [
            (self.moves[state][direction], numerator)
            for direction, numerator in self.slip_outcomes(state, action)
            if numerator > 0
        ]

    def reward(self, cell):
        index = self.world.terminal_index[cell]
        if index is None:
            return self.step_reward
        return self.world.terminal_rewards[index]

    def step(self, generator, state, action):
        draw = generator.draw() % self.slip_total
        slip = self.slip(state)
        if draw < self.slip_total - 2 * slip:
            direction = action
        elif draw < self.slip_total - slip:
            direction = (action + 1) % 4
        else:
            direction = (action + 3) % 4
        cell = self.moves[state][direction]
        return cell, self.reward(cell)

def discounted_return(rewards, gamma):
    value = 0
    for reward in reversed(rewards):
        value = 10000 * reward + gamma * value // 100
    return value


class ReturnAverages:
    def __init__(self, state_count):
        self.sums = [[0] * 4 for _ in range(state_count)]
        self.counts = [[0] * 4 for _ in range(state_count)]

    def update(self, q_values, history, gamma):
        seen = set()
        first_visits = []
        for state, action, _ in history:
            first_visits.append((state, action) not in seen)
            seen.add((state, action))
        value = 0
        for index in range(len(history) - 1, -1, -1):
            state, action, reward = history[index]
            value = 10000 * reward + gamma * value // 100
            if first_visits[index]:
                self.sums[state][action] += value
                self.counts[state][action] += 1
                q_values[state][action] = self.sums[state][action] // self.counts[state][action]

from environment import ACTION_LETTERS

POLICY_SYMBOLS = "^>v<"


def fixed_text(value):
    sign = "-" if value < 0 else ""
    whole, fraction = divmod(abs(value), 10000)
    return f"{sign}{whole}.{fraction:04d}"


def average_text(total, count):
    return fixed_text(10000 * total // count)


def cell_text(world, cell):
    row, col = divmod(cell, world.cols)
    return f"{row},{col}"


def cells_text(world, cells):
    return " ".join(cell_text(world, cell) for cell in cells)


def grid_lines(world, fields, separator):
    lines = []
    for row in range(world.rows):
        parts = []
        for cell in range(row * world.cols, (row + 1) * world.cols):
            state = world.state_index[cell]
            parts.append(world.kinds[cell] if state is None else fields[state])
        lines.append(separator.join(parts))
    return lines


def value_grid(world, values):
    return grid_lines(world, [fixed_text(value) for value in values], " ")


def policy_grid(world, policy):
    return grid_lines(world, [POLICY_SYMBOLS[action] for action in policy], "")


def symbol_grid(world, symbols):
    return grid_lines(world, symbols, "")


def q_table_rows(world, name, q_values, visits):
    rows = []
    for state, cell in enumerate(world.states):
        row, col = divmod(cell, world.cols)
        for action, letter in enumerate(ACTION_LETTERS):
            count = "-" if visits is None else str(visits[state][action])
            value = fixed_text(q_values[state][action])
            rows.append(f"{name},{row},{col},{letter},{value},{count}")
    return rows


def join_parts(parts):
    lines = []
    for part in parts:
        if lines:
            lines.append("")
        lines.extend(part)
    return lines


def write_lines(path, lines):
    with open(path, "w", newline="\n") as file:
        file.write("\n".join(lines) + "\n")

from dynamic_programming import first_max


def choose(generator, q_row, epsilon):
    if generator.draw() % 1000 < epsilon:
        return generator.draw() % 4
    return first_max(q_row)


def td_target(reward, terminal, next_value, gamma):
    if terminal:
        return 10000 * reward
    return 10000 * reward + gamma * next_value // 100


def expected_value(q_row, epsilon):
    return (epsilon * sum(q_row) + 4 * (1000 - epsilon) * max(q_row)) // 4000


def td_update(q_row, action, target, alpha):
    q_row[action] += alpha * (target - q_row[action]) // 100


class DynaModel:
    def __init__(self, state_count):
        self.outcomes = [[None] * 4 for _ in range(state_count)]
        self.pairs = []

    def record(self, state, action, reward, next_state):
        if self.outcomes[state][action] is None:
            self.pairs.append((state, action))
        self.outcomes[state][action] = (reward, next_state)

    def plan(self, generator, q_values, gamma, alpha, count):
        for _ in range(count):
            state, action = self.pairs[generator.draw() % len(self.pairs)]
            reward, next_state = self.outcomes[state][action]
            terminal = next_state is None
            next_value = 0 if terminal else max(q_values[next_state])
            target = td_target(reward, terminal, next_value, gamma)
            td_update(q_values[state], action, target, alpha)
